#!/usr/bin/env node
/**
 * Generate the active-skin @import in `src/app/globals.css` from `ACTIVE_SKIN`.
 *
 * Single source of truth = `ACTIVE_SKIN` in `src/config/skins.ts`. The `@import`
 * line in globals.css is AUTOGENERATED — never hand-edited. This lets the team
 * switch skins by editing ONE place (the TS const); the CSS import is reconciled
 * by this script (run in the pre-commit hook, like the other `generate:*`).
 *
 * Usage:
 *   pnpm generate:skin           # rewrite the @import to match ACTIVE_SKIN
 *   pnpm generate:skin --check   # exit 1 if out of sync (CI), don't write
 *
 * Why a generator and not a 2nd hand-edit: CSS can't read TS, so the `@import`
 * (build-time CSS) can't derive `ACTIVE_SKIN` (runtime TS) on its own.
 *
 * DERIVATIVE-TOLERANT (sk-skins §3): an app whose `src/` predates the skin split
 * (no `src/config/skins.ts`) is a VALID state — `factory update` never touches
 * `src/`, so every pre-v11 derivative runs this script via the shipped pre-commit
 * hook. Un-split src → clean no-op (exit 0), never a crash.
 *
 * Stays plain-node `.mjs` ON PURPOSE (not migrated to .ts like the other
 * generators): the shipped hook invokes it by path on heterogeneous derivatives,
 * and `tsx` is a dev-owned devDependency the kit cannot assume exists there.
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SKINS_CONFIG = join(ROOT, 'src/config/skins.ts');
const GLOBALS = join(ROOT, 'src/app/globals.css');
const SENTINEL = '@skin-import';

const check = process.argv.includes('--check');

function fail(msg) {
  console.error(`✖ generate:skin — ${msg}`);
  process.exit(1);
}

/** Un-split / non-Next src is a valid state (sk-skins §3) — exit 0, never crash. */
function skipUnsplit(reason) {
  console.log(`✓ generate:skin — ${reason}; skipping (pre-skin-split src is valid — sk-skins §3)`);
  process.exit(0);
}

// 0. Tolerance guards: a derivative src/ the update never touches may not have
//    the skin system at all. Only when the registry EXISTS is the split contract
//    enforceable (missing sentinel etc. then IS real drift → fail below).
if (!existsSync(SKINS_CONFIG)) {
  skipUnsplit('skin system not initialized (no src/config/skins.ts)');
}
if (!existsSync(GLOBALS)) {
  skipUnsplit('no src/app/globals.css in this repo');
}

// 1. Read ACTIVE_SKIN from the registry (regex over source — no transpile needed).
const configSrc = readFileSync(SKINS_CONFIG, 'utf8');
const activeMatch = configSrc.match(/export const ACTIVE_SKIN\s*:\s*SkinName\s*=\s*'([^']+)'/);
if (!activeMatch) fail(`could not find ACTIVE_SKIN in ${SKINS_CONFIG}`);
const skin = activeMatch[1];

// 2. The skin's CSS file must exist.
if (!existsSync(join(ROOT, `src/app/skins/${skin}.css`))) {
  fail(`ACTIVE_SKIN='${skin}' but src/app/skins/${skin}.css does not exist`);
}

// 3. Rewrite the line right after the sentinel comment in globals.css.
const css = readFileSync(GLOBALS, 'utf8');
const lines = css.split('\n');
const i = lines.findIndex((l) => l.includes(SENTINEL));
// Reaching here means skins.ts EXISTS → the app started the split → a missing
// sentinel is REAL drift of a split app (not the pre-v11 case, handled above).
if (i === -1)
  fail(
    `sentinel "${SENTINEL}" not found in ${GLOBALS}.\n` +
      `  The skin registry (src/config/skins.ts) exists, so globals.css must carry the\n` +
      `  autogenerated import block (sk-skins §3):\n` +
      `    /* ${SENTINEL} */\n    @import './skins/<skin>.css';\n` +
      `  Restore those two lines where the theme import belongs and re-run.`
  );
if (i + 1 >= lines.length) fail(`no @import line after the "${SENTINEL}" sentinel`);

const want = `@import './skins/${skin}.css';`;
const current = lines[i + 1];

if (current.trim() === want) {
  if (!check) console.log(`✓ generate:skin — @import already on '${skin}'`);
  process.exit(0);
}

if (check) {
  fail(
    `globals.css @import is out of sync with ACTIVE_SKIN='${skin}'.\n` +
      `  expected: ${want}\n  found:    ${current.trim()}\n` +
      `  → run \`pnpm generate:skin\``
  );
}

lines[i + 1] = want;
writeFileSync(GLOBALS, lines.join('\n'));
console.log(`✓ generate:skin — set globals.css @import to '${skin}'`);
